#include "cp_lp_core.h"

#include <string.h>

#include "sdkconfig.h"

#if CP_LP_CORE_BUILT

#include "ulp_lp_core.h"
#include "esp_log.h"

// Generated by IDF's esp32ulp_mapgen.py from the linked ULP binary
// (build/.../ulp_cp_lp_core/ulp_cp_lp_core.h): `extern uint32_t ulp_cp_lp_<name>`
// for every non-static global of the ULP program, resolved through the generated
// .ld that places them at their LP RAM addresses.
#include "ulp_cp_lp_core.h"

static const char* TAG = "cp_lp_core";

// The embedded image itself. target_add_binary_data() (components/ulp/
// project_include.cmake:117) puts it in this component's archive under the
// _binary_* names; unlike the program's variables these are NOT in the mapgen
// header, so declare them here — same shape as IDF's own lp_core example
// (examples/system/ulp/lp_core/gpio/main/lp_core_gpio_example_main.c:24-25).
extern const uint8_t ulp_cp_lp_core_bin_start[] asm("_binary_ulp_cp_lp_core_bin_start");
extern const uint8_t ulp_cp_lp_core_bin_end[] asm("_binary_ulp_cp_lp_core_bin_end");

// The variables below live in LP RAM and are declared by the ULP program as
// ordinary globals, so the mapgen header exposes them by name. The ULP core
// writes them behind the compiler's back; they are re-read on every access.
extern uint32_t ulp_cp_lp_counter;
extern uint32_t ulp_cp_lp_loops;
extern uint32_t ulp_cp_lp_magic;
extern uint32_t ulp_cp_lp_done;

static cp_lp_state_t s_state = CP_LP_STATE_IDLE;
static esp_err_t s_err = ESP_OK;

esp_err_t cp_lp_core_start(void) {
  // A second start must not run on top of a still-running LP core: stop it and
  // disable its wakeup sources first. ulp_lp_core_stop() is the documented way
  // (components/ulp/lp_core/lp_core.c:328) and is safe when the LP core is
  // already halted. This is what makes the Debug row re-tappable.
  ulp_lp_core_stop();

  // ulp_lp_core_load_binary() zeroes the whole reserved window before copying the
  // image in (lp_core.c:298), so the counter always starts the run at 0 — the
  // "delta" the row reports is therefore comparable between taps.
  s_err = ulp_lp_core_load_binary(ulp_cp_lp_core_bin_start,
                                 (size_t)(ulp_cp_lp_core_bin_end - ulp_cp_lp_core_bin_start));

  if (s_err != ESP_OK) {
    ESP_LOGE(TAG, "load_binary failed: %s", esp_err_to_name(s_err));
    s_state = CP_LP_STATE_ERROR;
    return s_err;
  }

  ulp_lp_core_cfg_t cfg = {
      .wakeup_source = ULP_LP_CORE_WAKEUP_SOURCE_HP_CPU,
      .lp_timer_sleep_duration_us = 0,
  };
  s_err = ulp_lp_core_run(&cfg);
  if (s_err != ESP_OK) {
    ESP_LOGE(TAG, "run failed: %s", esp_err_to_name(s_err));
    s_state = CP_LP_STATE_ERROR;
    return s_err;
  }
  s_state = CP_LP_STATE_RUNNING;
  return ESP_OK;
}

void cp_lp_core_stop(void) {
  ulp_lp_core_stop();
  if (s_state == CP_LP_STATE_RUNNING) s_state = CP_LP_STATE_IDLE;
}

cp_lp_state_t cp_lp_core_state(void) {
  // The ULP program is bounded and then returns (IDF halts the LP core on return
  // from main). done != 0 means it reached the end under its own steam; promote
  // RUNNING to DONE here so a caller polling state() does not have to know that.
  if (s_state == CP_LP_STATE_RUNNING && ulp_cp_lp_done != 0) s_state = CP_LP_STATE_DONE;
  return s_state;
}

esp_err_t cp_lp_core_last_err(void) { return s_err; }
uint32_t cp_lp_core_magic(void) { return ulp_cp_lp_magic; }
uint32_t cp_lp_core_counter(void) { return ulp_cp_lp_counter; }
uint32_t cp_lp_core_loops(void) { return ulp_cp_lp_loops; }
uint32_t cp_lp_core_done(void) { return ulp_cp_lp_done; }
uint32_t cp_lp_core_binary_size(void) {
  return (uint32_t)(ulp_cp_lp_core_bin_end - ulp_cp_lp_core_bin_start);
}

#else  // !CP_LP_CORE_BUILT — the switch is on but the ULP co-processor is not
       // compiled in. Every entry point is a defined, honest "not built".

esp_err_t cp_lp_core_start(void) { return ESP_ERR_NOT_SUPPORTED; }
void cp_lp_core_stop(void) {}
cp_lp_state_t cp_lp_core_state(void) { return CP_LP_STATE_NOT_BUILT; }
esp_err_t cp_lp_core_last_err(void) { return ESP_ERR_NOT_SUPPORTED; }
uint32_t cp_lp_core_magic(void) { return 0; }
uint32_t cp_lp_core_counter(void) { return 0; }
uint32_t cp_lp_core_loops(void) { return 0; }
uint32_t cp_lp_core_done(void) { return 0; }
uint32_t cp_lp_core_binary_size(void) { return 0; }

#endif  // CP_LP_CORE_BUILT
